-- =====================================================================
-- Portal Docente (UADEnet) — esquema de base de datos
-- PostgreSQL / Supabase. Pegar y ejecutar en el SQL Editor.
--
-- Datos propios del microservicio `teacher`: asistencia, exámenes,
-- calificaciones y actas (incluido el cierre y el resultado final de
-- cada alumno). Los ids de curso, asignatura, período, alumno y
-- docente son referencias a otros módulos (sin clave foránea).
--
-- Convenciones (pensadas para mapear a entidades JPA):
--   - PK: bigint identity            -> Long + @GeneratedValue(IDENTITY)
--   - Enums: varchar + check         -> enum Java + @Enumerated(STRING)
--   - Notas: numeric(4,2)            -> BigDecimal
--   - Fechas: date / time / timestamptz -> LocalDate / LocalTime / OffsetDateTime
--   - Enteros: integer               -> Integer
-- Guía de mapeo: docs/guia-backend-entities.md
-- =====================================================================

-- Para volver a crear todo desde cero, descomentar estas líneas.
-- ⚠️ Borra las tablas y sus datos.
-- drop view  if exists resultado_por_alumno, asistencia_por_alumno;
-- drop table if exists acta_detalle, acta, calificacion, examen, asistencia, clase cascade;


-- ---------------------------------------------------------------------
-- Asistencia
-- ---------------------------------------------------------------------

-- Una fila por cada clase en la que se tomó asistencia.
create table clase (
  id             bigint generated by default as identity primary key,
  curso_id       bigint      not null,          -- ref. Gestión Académica
  fecha          date        not null,
  observaciones  text,
  creado_por     varchar(50) not null,          -- docente que la registró (ref. externa)
  creado_en      timestamptz not null default now(),
  actualizado_en timestamptz not null default now(),
  constraint clase_curso_fecha_uk unique (curso_id, fecha)
);

-- Estado de cada alumno en una clase.
create table asistencia (
  id          bigint generated by default as identity primary key,
  clase_id    bigint      not null references clase (id) on delete cascade,
  alumno_id   varchar(50) not null,             -- ref. externa
  estado      varchar(15) not null
              check (estado in ('PRESENTE', 'AUSENTE', 'JUSTIFICADO')),
  observacion varchar(255),
  constraint asistencia_clase_alumno_uk unique (clase_id, alumno_id)
);

create index asistencia_alumno_idx on asistencia (alumno_id);


-- ---------------------------------------------------------------------
-- Exámenes y calificaciones
-- ---------------------------------------------------------------------

-- tipo es texto libre a propósito (PARCIAL_1, TP_1, FINAL, ...) para
-- poder sumar tipos nuevos sin cambiar el esquema.
create table examen (
  id               bigint generated by default as identity primary key,
  curso_id         bigint       not null,       -- ref. Gestión Académica
  tipo             varchar(50)  not null,
  nombre           varchar(100) not null,       -- ej. "Primer Parcial"
  descripcion      varchar(500),
  fecha            date         not null,
  hora_inicio      time         not null,
  duracion_minutos integer      not null check (duracion_minutos > 0),
  modalidad        varchar(15)  not null
                   check (modalidad in ('PRESENCIAL', 'VIRTUAL')),
  estado           varchar(15)  not null default 'PROGRAMADO'
                   check (estado in ('PROGRAMADO', 'CANCELADO')),
  creado_por       varchar(50)  not null,       -- ref. externa
  creado_en        timestamptz  not null default now(),
  actualizado_en   timestamptz  not null default now()
);

-- Un solo examen activo de cada tipo por curso; los cancelados no cuentan.
create unique index examen_curso_tipo_activo_uk
  on examen (curso_id, tipo)
  where estado <> 'CANCELADO';

create index examen_curso_idx on examen (curso_id);

-- Nota de un alumno en un examen.
create table calificacion (
  id          bigint generated by default as identity primary key,
  examen_id   bigint       not null references examen (id),
  alumno_id   varchar(50)  not null,            -- ref. externa
  nota        numeric(4,2) check (nota between 0 and 10),
  ausente     boolean      not null default false,
  cargada_por varchar(50)  not null,            -- ref. externa
  cargada_en  timestamptz  not null default now(),
  constraint calificacion_examen_alumno_uk unique (examen_id, alumno_id),
  constraint calificacion_ausente_sin_nota_ck check (not (ausente and nota is not null))
);

create index calificacion_alumno_idx on calificacion (alumno_id);


-- ---------------------------------------------------------------------
-- Actas (fuente oficial de la nota final y la condición del alumno)
-- ---------------------------------------------------------------------

-- Encabezado del acta. Materia, comisión, período y docente se copian
-- como texto al generarla: es un documento oficial y no debe cambiar
-- si después cambian los datos en otro módulo.
create table acta (
  id               bigint generated by default as identity primary key,
  numero           varchar(20)  not null unique, -- ej. 2026-001, lo genera el backend
  tipo             varchar(10)  not null check (tipo in ('CURSADA', 'FINAL')),
  curso_id         bigint       not null,        -- ref. Gestión Académica
  asignatura_id    bigint       not null,        -- ref. Gestión Académica
  periodo_id       bigint       not null,        -- ref. Gestión Académica
  examen_id        bigint       references examen (id),
  materia          varchar(150) not null,        -- copia: "Desarrollo de Aplicaciones II"
  comision         varchar(50)  not null,        -- copia: "DDA2-A"
  periodo          varchar(50)  not null,        -- copia: "2° Cuatrimestre 2026"
  docente_id       varchar(50)  not null,        -- ref. externa
  docente_nombre   varchar(150) not null,        -- copia, para la firma
  fecha            date         not null,
  observaciones    text,
  estado           varchar(10)  not null default 'GENERADA'
                   check (estado in ('GENERADA', 'ANULADA')),
  generada_en      timestamptz  not null default now(),
  anulada_en       timestamptz,
  motivo_anulacion text,
  -- Envío de resultados a Gestión Académica (PUT .../inscripciones/{alumnoId})
  sync_ok          integer      not null default 0,
  sync_error       integer      not null default 0,
  sync_en          timestamptz,
  -- Las actas finales apuntan a su examen final; las de cursada no.
  constraint acta_examen_segun_tipo_ck check ((tipo = 'FINAL') = (examen_id is not null)),
  constraint acta_anulacion_ck check ((estado = 'ANULADA') = (anulada_en is not null))
);

-- Un acta vigente por curso y tipo (y por examen, en las finales).
create unique index acta_vigente_uk
  on acta (curso_id, tipo, coalesce(examen_id, 0))
  where estado = 'GENERADA';

create index acta_curso_idx   on acta (curso_id);
create index acta_periodo_idx on acta (periodo_id);
create index acta_docente_idx on acta (docente_id);

-- Un renglón por alumno. Nombre y legajo se copian al generar el acta.
create table acta_detalle (
  id            bigint generated by default as identity primary key,
  acta_id       bigint       not null references acta (id) on delete cascade,
  orden         integer      not null check (orden > 0),
  alumno_id     varchar(50)  not null,           -- ref. externa
  alumno_nombre varchar(150) not null,
  alumno_legajo varchar(20)  not null,
  nota          numeric(4,2) check (nota between 0 and 10),
  resultado     varchar(15)  not null
                check (resultado in ('APROBADO', 'DESAPROBADO', 'REGULAR', 'LIBRE', 'AUSENTE')),
  constraint acta_detalle_alumno_uk unique (acta_id, alumno_id),
  constraint acta_detalle_orden_uk  unique (acta_id, orden)
);

create index acta_detalle_alumno_idx on acta_detalle (alumno_id);


-- ---------------------------------------------------------------------
-- Vistas (solo lectura; en Java: entidades @Immutable)
-- ---------------------------------------------------------------------

-- Regularidad por asistencia, sobre las clases registradas hasta hoy.
-- Regla: 75% o más = REGULAR; menos = LIBRE. JUSTIFICADO no es inasistencia.
create view asistencia_por_alumno
with (security_invoker = true) as
select
  c.curso_id,
  a.alumno_id,
  count(*)::integer                                        as clases_registradas,
  (count(*) filter (where a.estado = 'PRESENTE'))::integer    as presentes,
  (count(*) filter (where a.estado = 'JUSTIFICADO'))::integer as justificados,
  (count(*) filter (where a.estado = 'AUSENTE'))::integer     as inasistencias,
  round(100.0 * count(*) filter (where a.estado <> 'AUSENTE') / count(*), 2)
                                                           as porcentaje_asistencia,
  case
    when 100.0 * count(*) filter (where a.estado <> 'AUSENTE') / count(*) >= 75
      then 'REGULAR'
    else 'LIBRE'
  end                                                      as condicion
from asistencia a
join clase c on c.id = a.clase_id
group by c.curso_id, a.alumno_id;

-- Último resultado oficial de cada alumno por curso, según las actas
-- vigentes (la más reciente gana). Lo consume el Portal del Estudiante
-- para el historial: materia, cuatrimestre, nota y situación.
create view resultado_por_alumno
with (security_invoker = true) as
select distinct on (a.curso_id, d.alumno_id)
  d.alumno_id,
  a.curso_id,
  a.asignatura_id,
  a.periodo_id,
  a.materia,
  a.comision,
  a.periodo,
  d.nota,
  d.resultado,
  a.tipo        as tipo_acta,
  a.numero      as acta_numero,
  a.fecha       as fecha_resultado
from acta_detalle d
join acta a on a.id = d.acta_id
where a.estado = 'GENERADA'
order by a.curso_id, d.alumno_id, a.generada_en desc;


-- ---------------------------------------------------------------------
-- Seguridad
-- ---------------------------------------------------------------------

-- RLS activado sin políticas: la API pública de Supabase (clave anon)
-- no puede leer ni escribir estas tablas. El backend Spring Boot se
-- conecta por JDBC con el usuario de la base, que no está sujeto a RLS.
alter table clase        enable row level security;
alter table asistencia   enable row level security;
alter table examen       enable row level security;
alter table calificacion enable row level security;
alter table acta         enable row level security;
alter table acta_detalle enable row level security;
